// House Robber III. dfs returns {rob_this_node, skip_this_node}.
pair<long long,long long> dfs(TreeNode* node) {
    if (!node) return {0, 0};
    auto [lr, ls] = dfs(node->left);
    auto [rr, rs] = dfs(node->right);
    long long robHere  = node->val + ls + rs;        // children must be skipped
    long long skipHere = max(lr, ls) + max(rr, rs);  // children free to choose
    return {robHere, skipHere};
}
long long rob(TreeNode* root) { auto [a, b] = dfs(root); return max(a, b); }

def rob(root):
    def dfs(node):
        if not node: return (0, 0)        # (rob, skip)
        l = dfs(node.left)
        r = dfs(node.right)
        rob_here = node.val + l[1] + r[1]  # can't rob children
        skip_here = max(l) + max(r)        # children free
        return (rob_here, skip_here)
    return max(dfs(root))

class Solution {
    pair<int,int> dfs(TreeNode* r) {     // {rob, skip}
        if (!r) return {0, 0};
        auto [lr, ls] = dfs(r->left);
        auto [rr, rs] = dfs(r->right);
        int rob = r->val + ls + rs;
        int skip = max(lr, ls) + max(rr, rs);
        return {rob, skip};
    }
public:
    int rob(TreeNode* root) { auto [a, b] = dfs(root); return max(a, b); }
};

class Solution:
    def rob(self, root) -> int:
        def dfs(r):
            if not r:
                return (0, 0)
            lr, ls = dfs(r.left)
            rr, rs = dfs(r.right)
            rob = r.val + ls + rs
            skip = max(lr, ls) + max(rr, rs)
            return (rob, skip)
        return max(dfs(root))

class Solution {
    int cameras = 0;
    int dfs(TreeNode* r) {                 // 0 need, 1 covered, 2 camera
        if (!r) return 1;
        int L = dfs(r->left), R = dfs(r->right);
        if (L == 0 || R == 0) { cameras++; return 2; }
        if (L == 2 || R == 2) return 1;
        return 0;
    }
public:
    int minCameraCover(TreeNode* root) {
        if (dfs(root) == 0) cameras++;
        return cameras;
    }
};

class Solution:
    def minCameraCover(self, root) -> int:
        self.cameras = 0
        def dfs(r):
            if not r:
                return 1
            L, R = dfs(r.left), dfs(r.right)
            if L == 0 or R == 0:
                self.cameras += 1
                return 2
            if L == 2 or R == 2:
                return 1
            return 0
        if dfs(root) == 0:
            self.cameras += 1
        return self.cameras

class Solution {
    int dfs(TreeNode* r, int mx) {
        if (!r) return 0;
        int good = r->val >= mx ? 1 : 0;
        int nm = max(mx, r->val);
        return good + dfs(r->left, nm) + dfs(r->right, nm);
    }
public:
    int goodNodes(TreeNode* root) { return dfs(root, INT_MIN); }
};

class Solution:
    def goodNodes(self, root) -> int:
        def dfs(r, mx):
            if not r:
                return 0
            good = 1 if r.val >= mx else 0
            nm = max(mx, r.val)
            return good + dfs(r.left, nm) + dfs(r.right, nm)
        return dfs(root, float('-inf'))

class Solution {
    int moves = 0;
    int dfs(TreeNode* r) {
        if (!r) return 0;
        int L = dfs(r->left), R = dfs(r->right);
        moves += abs(L) + abs(R);
        return r->val - 1 + L + R;
    }
public:
    int distributeCoins(TreeNode* root) { dfs(root); return moves; }
};

class Solution:
    def distributeCoins(self, root) -> int:
        self.moves = 0
        def dfs(r):
            if not r:
                return 0
            L, R = dfs(r.left), dfs(r.right)
            self.moves += abs(L) + abs(R)
            return r.val - 1 + L + R
        dfs(root)
        return self.moves

class Solution {
    vector<vector<int>> adj; vector<int> sz, ans;
    void dfs1(int u, int p, int depth, long long& rootSum) {
        sz[u] = 1; rootSum += depth;
        for (int v : adj[u]) if (v != p) { dfs1(v, u, depth + 1, rootSum); sz[u] += sz[v]; }
    }
    void dfs2(int u, int p, int n) {
        for (int v : adj[u]) if (v != p) { ans[v] = ans[u] + n - 2 * sz[v]; dfs2(v, u, n); }
    }
public:
    vector<int> sumOfDistancesInTree(int n, vector<vector<int>>& edges) {
        adj.assign(n, {}); sz.assign(n, 0); ans.assign(n, 0);
        for (auto& e : edges) { adj[e[0]].push_back(e[1]); adj[e[1]].push_back(e[0]); }
        long long rootSum = 0; dfs1(0, -1, 0, rootSum); ans[0] = (int)rootSum;
        dfs2(0, -1, n);
        return ans;
    }
};

import sys
class Solution:
    def sumOfDistancesInTree(self, n: int, edges: list[list[int]]) -> list[int]:
        sys.setrecursionlimit(10**6)
        adj = [[] for _ in range(n)]
        for a, b in edges:
            adj[a].append(b); adj[b].append(a)
        sz = [1] * n
        ans = [0] * n
        def dfs1(u, p, depth):
            ans[0] += depth
            for v in adj[u]:
                if v != p:
                    dfs1(v, u, depth + 1)
                    sz[u] += sz[v]
        def dfs2(u, p):
            for v in adj[u]:
                if v != p:
                    ans[v] = ans[u] + n - 2 * sz[v]
                    dfs2(v, u)
        dfs1(0, -1, 0)
        dfs2(0, -1)
        return ans
